async function waitFor(assertion: () => void, timeout = 2000): Promise<void> {
  const start = Date.now();
  for (;;) {
    try {
      assertion();
      return;
    } catch {
      if (Date.now() - start > timeout) throw new Error('timed out');
      await new Promise(resolve => setTimeout(resolve, 10));
    }
  }
}
```

